// ============================================================================
// wave2_ip_20k board top (GENERATED by tools/gen_harness.py): run w2_selftest,
// report per-unit digests on UART.  Report = header + 40 unit lines x 32 chars,
// repeated ~0.5 s.
//   "W240 M=XXXXXXXXXX P=YYYYYYYYYY   \r\n"  (done/pass masks, 10 hex digits)
//   "Uii TAG V D=XXXXXXXX            \r\n"  per unit (V = P/F/S/X)
// ============================================================================
module top #(
    parameter [39:0] UNIT_EN = 40'hFF_FF_FF_FF_FF
) (
    input  wire clk,
    output wire uart_tx,
    output wire status_pass,
    output wire status_fail
);

localparam integer MSG_LEN = 1312;
localparam [24:0] REPORT_GAP_RELOAD = 25'd13_500_000;
localparam [1:0] TX_ASSERT    = 2'd0;
localparam [1:0] TX_WAIT_BUSY = 2'd1;
localparam [1:0] TX_WAIT_IDLE = 2'd2;

reg [12:0] reset_count = 13'd0;
wire rst_n = reset_count[12];

wire all_done, all_pass, any_fail;
wire [39:0] done_mask, pass_mask;
wire [31:0] digest_q;
wire [5:0]  digest_sel;

reg [7:0] tx_data;
reg tx_valid;
wire tx_ready;
wire tx_busy;

reg [10:0] msg_index;
reg report_active;
reg [1:0] tx_state;
reg [24:0] report_gap_count;

assign digest_sel = (msg_index >= 11'd32) ? (msg_index - 11'd32) >> 5 : 6'd0;

w2_selftest #(.UNIT_EN(UNIT_EN)) selftest (
    .clk(clk),
    .rst_n(rst_n),
    .all_done(all_done),
    .all_pass(all_pass),
    .any_fail(any_fail),
    .digest_sel(digest_sel),
    .digest_q(digest_q),
    .done_mask(done_mask),
    .pass_mask(pass_mask)
);

uart_tx #(
    .CLK_FRE(27),
    .BAUD_RATE(115200)
) uart (
    .clk(clk),
    .rst_n(rst_n),
    .tx_data(tx_data),
    .tx_data_valid(tx_valid),
    .tx_data_ready(tx_ready),
    .tx_pin(uart_tx),
    .tx_busy(tx_busy)
);

assign status_pass = all_done && all_pass;
assign status_fail = all_done && any_fail;

function [7:0] hex_nibble;
    input [3:0] value;
    begin
        if (value < 4'd10) hex_nibble = 8'h30 + value;
        else               hex_nibble = 8'h41 + (value - 4'd10);
    end
endfunction

function [31:0] unit_name;
    input [5:0] u;
    begin
        case (u)
            6'd0: unit_name = "DPC ";
            6'd1: unit_name = "DEM ";
            6'd2: unit_name = "AWB ";
            6'd3: unit_name = "GAM ";
            6'd4: unit_name = "CSC ";
            6'd5: unit_name = "GRY ";
            6'd6: unit_name = "CGR ";
            6'd7: unit_name = "NMS ";
            6'd8: unit_name = "DTH ";
            6'd9: unit_name = "HYS ";
            6'd10: unit_name = "HAR ";
            6'd11: unit_name = "FST ";
            6'd12: unit_name = "LBP ";
            6'd13: unit_name = "HOG ";
            6'd14: unit_name = "INT ";
            6'd15: unit_name = "SCL ";
            6'd16: unit_name = "HST ";
            6'd17: unit_name = "CLA ";
            6'd18: unit_name = "SAD ";
            6'd19: unit_name = "CRP ";
            6'd20: unit_name = "FDIF";
            6'd21: unit_name = "BGS ";
            6'd22: unit_name = "BBOX";
            6'd23: unit_name = "CCL ";
            6'd24: unit_name = "PRJ ";
            6'd25: unit_name = "CAN ";
            6'd26: unit_name = "MAC ";
            6'd27: unit_name = "PWM ";
            6'd28: unit_name = "QEI ";
            6'd29: unit_name = "STP ";
            6'd30: unit_name = "DMA ";
            6'd31: unit_name = "ILA ";
            6'd32: unit_name = "CRC ";
            6'd33: unit_name = "PRBS";
            6'd34: unit_name = "MBST";
            6'd35: unit_name = "BC3 ";
            6'd36: unit_name = "BDN ";
            6'd37: unit_name = "TMR ";
            6'd38: unit_name = "WDT ";
            6'd39: unit_name = "LFSR";
            default: unit_name = "????";
        endcase
    end
endfunction

function [7:0] report_char;
    input [10:0] index;
    input [39:0] done_v;
    input [39:0] pass_v;
    input [31:0] dg;
    reg [5:0]  unit;
    reg [4:0]  pos;
    reg [31:0] nm;
    begin
        unit = (index - 11'd32) >> 5;
        pos  = (index - 11'd32) & 5'd31;
        nm   = unit_name(unit);
        if (index < 11'd32) begin
            // Header: "W240 M=XXXXXXXXXX P=YYYYYYYYYY"
            case (index)
                11'd0:  report_char = "W";
                11'd1:  report_char = "2";
                11'd2:  report_char = "4";
                11'd3:  report_char = "0";
                11'd4:  report_char = " ";
                11'd5:  report_char = "M";
                11'd6:  report_char = "=";
                11'd7:  report_char = hex_nibble(done_v[39:36]);
                11'd8:  report_char = hex_nibble(done_v[35:32]);
                11'd9:  report_char = hex_nibble(done_v[31:28]);
                11'd10: report_char = hex_nibble(done_v[27:24]);
                11'd11: report_char = hex_nibble(done_v[23:20]);
                11'd12: report_char = hex_nibble(done_v[19:16]);
                11'd13: report_char = hex_nibble(done_v[15:12]);
                11'd14: report_char = hex_nibble(done_v[11:8]);
                11'd15: report_char = hex_nibble(done_v[7:4]);
                11'd16: report_char = hex_nibble(done_v[3:0]);
                11'd17: report_char = " ";
                11'd18: report_char = "P";
                11'd19: report_char = "=";
                11'd20: report_char = hex_nibble(pass_v[39:36]);
                11'd21: report_char = hex_nibble(pass_v[35:32]);
                11'd22: report_char = hex_nibble(pass_v[31:28]);
                11'd23: report_char = hex_nibble(pass_v[27:24]);
                11'd24: report_char = hex_nibble(pass_v[23:20]);
                11'd25: report_char = hex_nibble(pass_v[19:16]);
                11'd26: report_char = hex_nibble(pass_v[15:12]);
                11'd27: report_char = hex_nibble(pass_v[11:8]);
                11'd28: report_char = hex_nibble(pass_v[7:4]);
                11'd29: report_char = hex_nibble(pass_v[3:0]);
                11'd30: report_char = 8'h0d;
                11'd31: report_char = 8'h0a;
                default: report_char = " ";
            endcase
        end else begin
            // Unit line: "Uii TAG V D=XXXXXXXX"
            case (pos)
                5'd0:  report_char = "U";
                5'd1:  report_char = hex_nibble({2'b0, unit[5:4]});
                5'd2:  report_char = hex_nibble(unit[3:0]);
                5'd3:  report_char = " ";
                5'd4:  report_char = nm[31:24];
                5'd5:  report_char = nm[23:16];
                5'd6:  report_char = nm[15:8];
                5'd7:  report_char = nm[7:0];
                5'd8:  report_char = " ";
                5'd9:  report_char = !UNIT_EN[unit] ? "S" :
                                     (pass_v[unit] ? "P" :
                                      (done_v[unit] ? "F" : "X"));
                5'd10: report_char = " ";
                5'd11: report_char = "D";
                5'd12: report_char = "=";
                5'd13: report_char = hex_nibble(dg[31:28]);
                5'd14: report_char = hex_nibble(dg[27:24]);
                5'd15: report_char = hex_nibble(dg[23:20]);
                5'd16: report_char = hex_nibble(dg[19:16]);
                5'd17: report_char = hex_nibble(dg[15:12]);
                5'd18: report_char = hex_nibble(dg[11:8]);
                5'd19: report_char = hex_nibble(dg[7:4]);
                5'd20: report_char = hex_nibble(dg[3:0]);
                5'd30: report_char = 8'h0d;
                5'd31: report_char = 8'h0a;
                default: report_char = " ";
            endcase
        end
    end
endfunction

always @(posedge clk) begin
    if (!rst_n) reset_count <= reset_count + 13'd1;
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        tx_data <= 8'd0;
        tx_valid <= 1'b0;
        msg_index <= 11'd0;
        report_active <= 1'b0;
        tx_state <= TX_ASSERT;
        report_gap_count <= 25'd0;
    end else begin
        if (all_done && !report_active) begin
            if (report_gap_count == 25'd0) begin
                report_active <= 1'b1;
                msg_index <= 11'd0;
                tx_state <= TX_ASSERT;
                tx_valid <= 1'b0;
            end else begin
                report_gap_count <= report_gap_count - 25'd1;
                tx_valid <= 1'b0;
            end
        end else if (report_active) begin
            case (tx_state)
                TX_ASSERT: begin
                    if (msg_index < MSG_LEN) begin
                        if (tx_ready) begin
                            tx_data <= report_char(msg_index, done_mask, pass_mask, digest_q);
                            tx_valid <= 1'b1;
                            tx_state <= TX_WAIT_BUSY;
                        end else begin
                            tx_valid <= 1'b0;
                        end
                    end else begin
                        tx_valid <= 1'b0;
                        report_active <= 1'b0;
                        report_gap_count <= REPORT_GAP_RELOAD;
                    end
                end

                TX_WAIT_BUSY: begin
                    if (tx_busy) begin
                        tx_valid <= 1'b0;
                        tx_state <= TX_WAIT_IDLE;
                    end else begin
                        tx_valid <= 1'b1;
                    end
                end

                TX_WAIT_IDLE: begin
                    tx_valid <= 1'b0;
                    if (tx_ready) begin
                        msg_index <= msg_index + 11'd1;
                        tx_state <= TX_ASSERT;
                    end
                end

                default: begin
                    tx_valid <= 1'b0;
                    tx_state <= TX_ASSERT;
                end
            endcase
        end else begin
            tx_valid <= 1'b0;
        end
    end
end

endmodule
